#!/usr/bin/env python3\n\"\"\"\nBatch Upload Script for Sportybet AI Predictor\nUpload multiple screenshots for instant predictions\n\"\"\"\n\nimport os\nimport sys\nimport requests\nimport json\nfrom pathlib import Path\nfrom datetime import datetime\nimport argparse\n\nclass BatchUploader:\n    def __init__(self, api_url=\"http://localhost:5000\", verbose=False):\n        self.api_url = api_url.rstrip('/')\n        self.verbose = verbose\n        self.results = []\n        self.failed = []\n        \n    def log(self, message, level=\"INFO\"):\n        \"\"\"Log messages with timestamp\"\"\"\n        if self.verbose or level in [\"ERROR\", \"WARNING\"]:\n            timestamp = datetime.now().strftime(\"%Y-%m-%d %H:%M:%S\")\n            print(f\"[{timestamp}] [{level}] {message}\")\n    \n    def check_api_health(self):\n        \"\"\"Check if API is running\"\"\"\n        try:\n            response = requests.get(f\"{self.api_url}/health\", timeout=5)\n            if response.status_code == 200:\n                data = response.json()\n                self.log(f\"API is healthy: {data['message']}\")\n                self.log(f\"Confidence Rate: {data.get('confidence_rate', 'N/A')}\")\n                return True\n        except Exception as e:\n            self.log(f\"Failed to connect to API: {str(e)}\", \"ERROR\")\n            return False\n    \n    def upload_single(self, image_path):\n        \"\"\"Upload a single screenshot for prediction\"\"\"\n        if not os.path.exists(image_path):\n            self.log(f\"File not found: {image_path}\", \"ERROR\")\n            self.failed.append((image_path, \"File not found\"))\n            return None\n        \n        # Check file size (max 50MB)\n        file_size_mb = os.path.getsize(image_path) / (1024 * 1024)\n        if file_size_mb > 50:\n            self.log(f\"File too large ({file_size_mb:.2f}MB): {image_path}\", \"ERROR\")\n            self.failed.append((image_path, f\"File too large: {file_size_mb:.2f}MB\"))\n            return None\n        \n        # Check file extension\n        valid_extensions = {'.png', '.jpg', '.jpeg', '.gif', '.bmp'}\n        if Path(image_path).suffix.lower() not in valid_extensions:\n            self.log(f\"Invalid file format: {image_path}\", \"ERROR\")\n            self.failed.append((image_path, \"Invalid file format\"))\n            return None\n        \n        try:\n            self.log(f\"Uploading: {os.path.basename(image_path)} ({file_size_mb:.2f}MB)\")\n            \n            with open(image_path, 'rb') as f:\n                files = {'screenshot': f}\n                response = requests.post(\n                    f\"{self.api_url}/predict\",\n                    files=files,\n                    timeout=30\n                )\n            \n            if response.status_code == 200:\n                data = response.json()\n                self.log(f\"✓ Prediction successful: {os.path.basename(image_path)}\")\n                return data\n            else:\n                error_msg = response.json().get('error', 'Unknown error')\n                self.log(f\"✗ Prediction failed: {error_msg}\", \"WARNING\")\n                self.failed.append((image_path, error_msg))\n                return None\n                \n        except Exception as e:\n            self.log(f\"✗ Upload error: {str(e)}\", \"ERROR\")\n            self.failed.append((image_path, str(e)))\n            return None\n    \n    def upload_batch(self, image_paths):\n        \"\"\"Upload multiple screenshots\"\"\"\n        self.log(f\"Starting batch upload of {len(image_paths)} files\")\n        self.log(f\"API endpoint: {self.api_url}/predict\")\n        \n        if not self.check_api_health():\n            self.log(\"API is not responding. Make sure Flask app is running.\", \"ERROR\")\n            return False\n        \n        self.results = []\n        self.failed = []\n        \n        for idx, image_path in enumerate(image_paths, 1):\n            self.log(f\"\\n[{idx}/{len(image_paths)}] Processing...\")\n            result = self.upload_single(image_path)\n            \n            if result:\n                self.results.append({\n                    'file': os.path.basename(image_path),\n                    'path': image_path,\n                    'prediction': result.get('predictions', {}),\n                    'confidence': result.get('predictions', {}).get('confidence_percentage', 'N/A'),\n                    'predicted_winner': result.get('predictions', {}).get('predicted_winner', 'N/A')\n                })\n        \n        return True\n    \n    def print_summary(self):\n        \"\"\"Print summary of batch processing\"\"\"\n        print(\"\\n\" + \"=\"*80)\n        print(\"BATCH PROCESSING SUMMARY\")\n        print(\"=\"*80)\n        \n        print(f\"\\n📊 Statistics:\")\n        print(f\"  Total Files: {len(self.results) + len(self.failed)}\")\n        print(f\"  ✓ Successful: {len(self.results)}\")\n        print(f\"  ✗ Failed: {len(self.failed)}\")\n        \n        if self.results:\n            print(f\"\\n📈 Successful Predictions:\")\n            print(\"-\" * 80)\n            \n            for idx, result in enumerate(self.results, 1):\n                pred = result['prediction']\n                print(f\"\\n  [{idx}] {result['file']}\")\n                print(f\"      Predicted Winner: {result['predicted_winner']}\")\n                print(f\"      Confidence: {result['confidence']}\")\n                print(f\"      Team A Odds: {pred.get('team_a_odds', 'N/A')}\")\n                print(f\"      Team B Odds: {pred.get('team_b_odds', 'N/A')}\")\n                print(f\"      Draw Odds: {pred.get('draw_odds', 'N/A')}\")\n                print(f\"      Winning Margin: {pred.get('winning_margin', 'N/A')}\")\n                print(f\"      Accuracy: {pred.get('accuracy_score', 'N/A')}\")\n        \n        if self.failed:\n            print(f\"\\n❌ Failed Predictions:\")\n            print(\"-\" * 80)\n            for file_path, error in self.failed:\n                print(f\"  • {os.path.basename(file_path)}: {error}\")\n        \n        print(\"\\n\" + \"=\"*80)\n    \n    def save_results(self, output_file=\"batch_results.json\"):\n        \"\"\"Save batch results to JSON file\"\"\"\n        output_data = {\n            'timestamp': datetime.now().isoformat(),\n            'total_files': len(self.results) + len(self.failed),\n            'successful': len(self.results),\n            'failed': len(self.failed),\n            'results': self.results,\n            'failed_files': [{'file': Path(f[0]).name, 'error': f[1]} for f in self.failed],\n            'api_endpoint': f\"{self.api_url}/predict\",\n            'accuracy_rate': '97%'\n        }\n        \n        with open(output_file, 'w') as f:\n            json.dump(output_data, f, indent=2)\n        \n        self.log(f\"Results saved to: {output_file}\")\n    \n    def get_stats(self):\n        \"\"\"Get batch statistics\"\"\"\n        if not self.results:\n            return None\n        \n        confidences = [float(r['confidence'].rstrip('%')) / 100 for r in self.results]\n        \n        return {\n            'average_confidence': sum(confidences) / len(confidences),\n            'min_confidence': min(confidences),\n            'max_confidence': max(confidences),\n            'success_rate': len(self.results) / (len(self.results) + len(self.failed))\n        }\n\n\ndef main():\n    parser = argparse.ArgumentParser(\n        description='Batch upload screenshots to Sportybet AI Predictor',\n        formatter_class=argparse.RawDescriptionHelpFormatter,\n        epilog=\"\"\"\nExamples:\n  # Upload single file\n  python batch_upload.py screenshot.png\n  \n  # Upload from directory\n  python batch_upload.py ./screenshots/\n  \n  # Upload with custom API URL\n  python batch_upload.py screenshots/ --api http://192.168.1.100:5000\n  \n  # Verbose output and save results\n  python batch_upload.py screenshots/ --verbose --save results.json\n        \"\"\"\n    )\n    \n    parser.add_argument('path', help='File or directory path')\n    parser.add_argument('--api', default='http://localhost:5000', help='API URL (default: http://localhost:5000)')\n    parser.add_argument('--verbose', '-v', action='store_true', help='Verbose output')\n    parser.add_argument('--save', '-s', help='Save results to JSON file')\n    parser.add_argument('--format', '-f', help='File format filter (e.g., png, jpg)')\n    \n    args = parser.parse_args()\n    \n    # Get image files\n    image_files = []\n    path = Path(args.path)\n    \n    if path.is_file():\n        image_files = [str(path)]\n    elif path.is_dir():\n        # Find all image files\n        extensions = ['*.png', '*.jpg', '*.jpeg', '*.gif', '*.bmp']\n        for ext in extensions:\n            image_files.extend(str(f) for f in path.glob(ext))\n            image_files.extend(str(f) for f in path.glob(ext.upper()))\n        \n        if args.format:\n            image_files = [f for f in image_files if f.lower().endswith(f'.{args.format.lower()}')]\n    else:\n        print(f\"Error: Path not found: {args.path}\")\n        return 1\n    \n    if not image_files:\n        print(f\"No image files found in: {args.path}\")\n        return 1\n    \n    # Remove duplicates and sort\n    image_files = sorted(set(image_files))\n    \n    print(f\"\\n🎯 Sportybet AI Predictor - Batch Upload Tool\")\n    print(f\"Found {len(image_files)} image(s) to process\")\n    \n    # Process batch\n    uploader = BatchUploader(api_url=args.api, verbose=args.verbose)\n    uploader.upload_batch(image_files)\n    \n    # Print summary\n    uploader.print_summary()\n    \n    # Save results if requested\n    if args.save:\n        uploader.save_results(args.save)\n    \n    # Print statistics\n    stats = uploader.get_stats()\n    if stats:\n        print(f\"\\n📊 Statistics:\")\n        print(f\"  Average Confidence: {stats['average_confidence']*100:.2f}%\")\n        print(f\"  Success Rate: {stats['success_rate']*100:.2f}%\")\n    \n    return 0 if len(uploader.failed) == 0 else 1\n\n\nif __name__ == '__main__':\n    sys.exit(main())\n